const headers = $json.headers || {};
const providedSecret = headers['x-fbc-webhook-secret'] || headers['X-FBC-Webhook-Secret'];
const expectedSecret = $env.N8N_WEBHOOK_SECRET;

// Keep failed authentication isolated from the request body so it cannot have side effects.
if (typeof providedSecret !== 'string' || typeof expectedSecret !== 'string' || providedSecret !== expectedSecret) {
  return [{ json: { authorized: false } }];
}

const body = $json.body && typeof $json.body === 'object' ? $json.body : {};
return [{
  json: {
    authorized: true,
    action: body.action,
    requestId: headers['x-fbc-request-id'] || headers['X-FBC-Request-Id'] || body.requestId,
    email: body.email,
    page: body.page,
    marketingConsent: body.marketingConsent === true,
    consentVersion: body.consentVersion || '',
    recipe: body.recipe || null,
    receivedAt: new Date().toISOString()
  }
}];

const data = $input.first().json;
const recipe = data.recipe || {};
const escapeHtml = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\"/g, '&quot;')
  .replace(/'/g, '&#39;');
const plain = (value) => String(value ?? '').replace(/[\r\n]+/g, ' ').trim();
const safe = (value, fallback = '') => escapeHtml(plain(value) || fallback);
const websiteUrl = 'https://freezerbatchcocktails.com';
const unsubscribeUrl = 'https://freezerbatchcocktails.com/unsubscribe';
const ingredients = Array.isArray(recipe.ingredients) ? recipe.ingredients : [];
const ingredientRows = ingredients.length
  ? ingredients.map((ingredient) => `<tr><td style="padding:12px 0;border-bottom:1px solid #3b342e;color:#f4ede3;">${safe(ingredient.name)}</td><td style="padding:12px 0;border-bottom:1px solid #3b342e;text-align:right;color:#d7b46a;">${safe(ingredient.amount)}</td></tr>`).join('')
  : '<tr><td colspan="2" style="padding:12px 0;color:#c8c0b7;">Your ingredient list is in the calculator.</td></tr>';
const recipeName = safe(recipe.name, 'Freezer Batch');
const abv = safe(recipe.abv, '—');
const servings = safe(recipe.servings, '—');
const bottleSize = safe(recipe.bottleSize, '—');
const dilution = safe(recipe.dilution, '—');
const pourOff = safe(recipe.pourOff, '0 ml');
const waterToAdd = safe(recipe.waterToAdd, '0 ml');
const html = `<!doctype html><html><body style="margin:0;background:#171411;color:#f4ede3;font-family:Arial,sans-serif;"><table role="presentation" width="100%" cellspacing="0" cellpadding="0"><tr><td align="center" style="padding:32px 16px;"><table role="presentation" width="600" cellspacing="0" cellpadding="0" style="max-width:600px;background:#241f1a;border:1px solid #3b342e;"><tr><td style="padding:36px;background:#0e0c0a;border-bottom:4px solid #d7b46a;"><p style="margin:0 0 8px;color:#d7b46a;letter-spacing:2px;font-size:12px;">FREEZER BATCH COCKTAILS</p><h1 style="margin:0;color:#f4ede3;font-size:30px;">${recipeName}</h1></td></tr><tr><td style="padding:32px;"><p style="margin:0 0 20px;color:#c8c0b7;line-height:1.6;">A measured batch for your freezer door.</p><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="margin:0 0 24px;"><tr><td style="color:#d7b46a;">ABV<br><strong style="color:#f4ede3;">${abv}</strong></td><td style="color:#d7b46a;">DRINKS<br><strong style="color:#f4ede3;">${servings}</strong></td><td style="color:#d7b46a;">BOTTLE<br><strong style="color:#f4ede3;">${bottleSize}</strong></td><td style="color:#d7b46a;">DILUTION<br><strong style="color:#f4ede3;">${dilution}</strong></td></tr></table><p style="padding:14px;border-left:3px solid #d7b46a;background:#2d271f;color:#f4ede3;"><strong>First:</strong> pour off ${pourOff} to make room.</p><h2 style="color:#f4ede3;font-size:20px;">Add these ingredients</h2><table role="presentation" width="100%" cellspacing="0" cellpadding="0">${ingredientRows}<tr><td style="padding:12px 0;color:#f4ede3;">Water (dilution)</td><td style="padding:12px 0;text-align:right;color:#d7b46a;">${waterToAdd}</td></tr></table><p style="color:#c8c0b7;line-height:1.6;"><strong style="color:#f4ede3;">Freezer note:</strong> cocktails under 22% ABV may freeze too firm to pour. Fresh citrus evolves in the freezer; for longer storage, batch the spirits and add fresh citrus when serving.</p><p style="margin:28px 0 0;"><a href="${escapeHtml(websiteUrl)}/cocktails" style="background:#d7b46a;color:#171411;padding:13px 20px;text-decoration:none;font-weight:bold;">Browse cocktails</a></p></td></tr><tr><td style="padding:22px 32px;background:#0e0c0a;color:#a69d93;font-size:12px;">Freezer Batch Cocktails · <a href="${escapeHtml(unsubscribeUrl)}" style="color:#d7b46a;">Unsubscribe from marketing</a></td></tr></table></td></tr></table></body></html>`;
const text = `FREEZER BATCH COCKTAILS\n\n${plain(recipe.name) || 'Freezer Batch'}\nABV: ${plain(recipe.abv) || '—'} · Drinks: ${plain(recipe.servings) || '—'} · Bottle: ${plain(recipe.bottleSize) || '—'}\n\nFirst, pour off ${plain(recipe.pourOff) || '0 ml'} to make room.\n\nIngredients:\n${ingredients.map((ingredient) => `- ${plain(ingredient.name)}: ${plain(ingredient.amount)}`).join('\n')}\n- Water (dilution): ${plain(recipe.waterToAdd) || '0 ml'}\n\nFreezer note: cocktails under 22% ABV may freeze too firm to pour. Fresh citrus evolves in the freezer; for longer storage, batch the spirits and add fresh citrus when serving.\n\nBrowse cocktails: ${websiteUrl}/cocktails`;
return [{ json: { ...data, html, text, subject: `Your ${plain(recipe.name) || 'Freezer Batch'} recipe` } }];

// HTTP Request outputs Resend's response, so restore the normalized request for the consent decision.
const request = $('Build Transactional Recipe Email').item.json;
return [{ json: request }];

